// ======================================================
// CONFIGURATION DES LANGUES ET DES DRAPEAUX
// ======================================================

const languageNames = {
  fr: { flag: "fr", name: "Français" },
  en: { flag: "gb", name: "English" },
  de: { flag: "de", name: "Deutsch" },
  es: { flag: "es", name: "Español" },
  nl: { flag: "nl", name: "Nederlands" }
};

const LANGUAGE_STORAGE_KEY = "ticketcheck_language";

let currentLanguage = localStorage.getItem(LANGUAGE_STORAGE_KEY) || "fr";

if (!translations[currentLanguage]) {
  currentLanguage = "fr";
}

// ======================================================
// TRADUCTIONS
// ======================================================

function getLanguage() {
  return currentLanguage;
}

function t(key) {
  return translations[currentLanguage]?.[key]
    ?? translations.fr[key]
    ?? key;
}

function applyTranslations() {
  document.documentElement.lang = currentLanguage;

  document.querySelectorAll("[data-i18n]").forEach((element) => {
    const key = element.getAttribute("data-i18n");
    element.textContent = t(key);
  });

  document.querySelectorAll("[data-i18n-placeholder]").forEach((element) => {
    const key = element.getAttribute("data-i18n-placeholder");
    element.placeholder = t(key);
  });

  document.querySelectorAll("[data-i18n-title]").forEach((element) => {
    const key = element.getAttribute("data-i18n-title");
    element.title = t(key);
  });

  document.querySelectorAll("[data-i18n-value]").forEach((element) => {
    const key = element.getAttribute("data-i18n-value");
    element.value = t(key);
  });

  document.dispatchEvent(
    new CustomEvent("ticketcheck:languageChanged", {
      detail: { language: currentLanguage }
    })
  );
}

// ======================================================
// AFFICHAGE DES DRAPEAUX
// ======================================================

function flagImage(code) {
  const language = languageNames[code];

  return `
    <img
      class="tc-language-flag"
      src="https://flagcdn.com/w40/${language.flag}.png"
      alt="Drapeau ${language.name}"
      width="26"
      height="18"
      loading="eager"
      decoding="async"
    >
  `;
}

// ======================================================
// MISE À JOUR DU BOUTON DE LANGUE
// ======================================================

function updateLanguageButton() {
  const button = document.getElementById("ticketcheck-language-button");

  if (!button) return;

  const selected = languageNames[currentLanguage];

  button.innerHTML = `
    ${flagImage(currentLanguage)}
    <span>${selected.name}</span>
    <span class="tc-language-arrow">▾</span>
  `;
}

// ======================================================
// CHANGEMENT DE LANGUE
// ======================================================

function setLanguage(language) {
  if (!translations[language]) return;

  currentLanguage = language;

  localStorage.setItem(LANGUAGE_STORAGE_KEY, language);

  applyTranslations();
  updateLanguageButton();

  document.querySelectorAll(".tc-language-option").forEach((option) => {
    const isSelected = option.dataset.language === language;

    option.classList.toggle("active", isSelected);
    option.setAttribute("aria-pressed", String(isSelected));
  });

  const menu = document.getElementById("ticketcheck-language-menu");

  if (menu) {
    menu.hidden = true;
  }

  const button = document.getElementById("ticketcheck-language-button");

  if (button) {
    button.setAttribute("aria-expanded", "false");
  }
}

